begin;
do $$
declare admin uuid; customer uuid; result jsonb; duplicate jsonb; prod uuid; ord uuid; item uuid; caught boolean; amount numeric; pay text:=gen_random_uuid()::text; path text;
begin
 select id into admin from profiles where role='admin' limit 1;
 select id into customer from profiles where id<>admin order by created_at limit 1;
 insert into discord_account_links(profile_id,discord_user_id,discord_username) values(customer,'999999999999999971','store-fixture'),(admin,'999999999999999972','admin-fixture') on conflict(profile_id) do update set discord_user_id=excluded.discord_user_id;
 caught:=false;begin perform discord_create_product('999999999999999971','999999999999999970','999999999999999973','test-create-denied','{"name":"Fixture","price":10,"mode":"manual"}');exception when others then if sqlerrm='FORBIDDEN' then caught:=true;else raise;end if;end;if not caught then raise exception 'customer created product';end if;
 result:=discord_create_product('999999999999999972','999999999999999970','999999999999999973','test-create-store','{"name":"Fixture","price":10,"mode":"key","description":"test"}');prod:=(result->>'product_id')::uuid;
 duplicate:=discord_create_product('999999999999999972','999999999999999970','999999999999999973','test-create-store','{"name":"Another","price":20,"mode":"manual"}');if result->>'product_id'<>duplicate->>'product_id' then raise exception 'duplicate product';end if;
 if not exists(select from discord_sales_panels where id=(result->>'panel_id')::uuid and product_ids=array[prod]) then raise exception 'panel not created atomically';end if;
 perform discord_configure_product_delivery('999999999999999972','999999999999999970',prod,'role','{"role_id":"999999999999999974"}');
 result:=discord_prepare_checkout('test-role-order','999999999999999971','999999999999999970','999999999999999973',prod);ord:=(result->>'order_id')::uuid;
 select order_item_id into item from discord_order_fulfilments where order_id=ord;
 if item is null then raise exception 'role snapshot missing';end if;
 perform discord_configure_product_delivery('999999999999999972','999999999999999970',prod,'role','{"role_id":"999999999999999975"}');
 if (select role_id from discord_order_fulfilments where order_item_id=item)<>'999999999999999974' then raise exception 'purchase snapshot changed';end if;
 caught:=false;begin perform discord_complete_product_delivery(item);exception when others then if sqlerrm='ORDER_NOT_PAID' then caught:=true;else raise;end if;end;if not caught then raise exception 'unpaid delivered';end if;
 insert into payments(order_id,provider,provider_payment_id,status,amount) values(ord,'turbofypay',pay,'pending',10);
 perform discord_settle_payment(pay,jsonb_build_object('id',pay,'status','PAID','amountCents',1000));
 if (select status from orders where id=ord)<>'paid' then raise exception 'role delivered before API';end if;
 if not exists(select from jsonb_array_elements(discord_pending_fulfilments()) q where q->>'order_id'=ord::text) then raise exception 'delivery not queued';end if;
 perform discord_complete_product_delivery(item);perform discord_complete_product_delivery(item);
 if (select count(*) from order_deliveries where order_item_id=item)<>1 or (select status from orders where id=ord)<>'delivered' then raise exception 'role completion not idempotent';end if;
 path:=admin||'/discord-products/test-fixture.txt';
 insert into storage.objects(bucket_id,name) values('support-files',path);
 perform discord_configure_product_delivery('999999999999999972','999999999999999970',prod,'file',jsonb_build_object('attachment_path',path,'attachment_name','fixture.txt'));
 result:=discord_prepare_checkout('test-file-order','999999999999999971','999999999999999970','999999999999999973',prod);ord:=(result->>'order_id')::uuid;
 select order_item_id into item from discord_order_fulfilments where order_id=ord;
 if exists(select from order_deliveries where order_item_id=item) then raise exception 'unpaid file exposed';end if;
 insert into payments(order_id,provider,provider_payment_id,status,amount) values(ord,'turbofypay','file-'||pay,'pending',10);
 perform discord_settle_payment('file-'||pay,jsonb_build_object('id','file-'||pay,'status','PAID','amountCents',1000));
 perform discord_complete_product_delivery(item);
 if not exists(select from order_deliveries where order_item_id=item and attachment_path=path) then raise exception 'file delivery missing';end if;
 insert into discord_ai_settings(guild_id,enabled,hourly_limit) values('999999999999999970',true,1);
 perform discord_reserve_store_ai('999999999999999972','999999999999999970','test-store-ai');
 caught:=false;begin perform discord_reserve_store_ai('999999999999999972','999999999999999970','test-store-ai-limit');exception when others then if sqlerrm='AI_LIMIT_REACHED' then caught:=true;else raise;end if;end;if not caught then raise exception 'AI quota failed';end if;
 if has_table_privilege('authenticated','discord_order_fulfilments','select') or has_table_privilege('anon','discord_product_fulfilments','select') or has_function_privilege('authenticated','discord_complete_product_delivery(uuid)','execute') or has_function_privilege('authenticated','discord_create_product(text,text,text,text,jsonb)','execute') then raise exception 'private store API exposed';end if;
end $$;
select 'PASS: admin-only product creation, atomic panel/replay, immutable role/file snapshots, paid-only idempotent delivery, retry queue and AI quota; rolled back' as test_result;
rollback;
